/* Original Unit 3 study questions. Correct answer is an index into choices.
   To add a question, add a row to the matching topic. Runtime shuffles indices. */
(function(root) {
  const groups = [
    ['purpose', 'Purpose, inputs & outputs', 'What apps do, and how people interact with them.', [
      ['Easy','Which best describes the purpose of a bus-arrival app?',['Help riders decide when to reach a bus stop','Use as many screens as possible','Show the programmer’s favorite colors','Run every available command'],'A program’s purpose is the problem it solves or need it serves.'],
      ['Easy','In a music app, a person taps Pause. What is the input?',['The person’s tap','The music stopping','The album cover appearing','The speaker becoming quiet'],'Input is information or an action supplied to the program; the tap triggers a response.'],
      ['Easy','A weather app displays a forecast. The displayed forecast is what?',['Output','An event handler','A code comment','A programming language'],'Output is information or an effect a program produces.'],
      ['Medium','A museum app lets visitors choose a room, then shows directions. Which pair correctly identifies input and output?',['Room choice → directions displayed','Directions displayed → room choice','Screen color → programming language','App title → source code'],'The visitor supplies the room choice, and the app produces directions.'],
      ['Medium','Which statement describes an app’s purpose rather than an implementation detail?',['Help students find an available study room','Call setScreen("rooms")','Place a button at x = 30','Use three onEvent handlers'],'Purpose explains why the app exists; the other statements describe how it is built.'],
      ['Easy','Which is an example of audio output?',['A chime played when a timer finishes','A click on the Start button','A number typed into a box','A screen ID written in code'],'The chime is produced by the program and heard by the user.'],
      ['Medium','A library app’s goal is to help readers locate books. Which feature most directly serves that goal?',['Display a selected book’s shelf location','Play a random song on launch','Change the background every second','Show unrelated sports scores'],'A shelf location helps the intended user solve the app’s stated problem.'],
      ['Hard','An app displays “Ready” when it launches and waits for a tap before displaying “Go.” Which statement is accurate?',['It can produce output before receiving a user tap','Every output requires a previous user tap','“Ready” is input because it appears first','Waiting for a tap prevents all startup code'],'Startup statements can produce output; event handlers can produce additional output later.'],
      ['Medium','A person types “Maya” into a name field. Which is the clearest example of that app receiving data as input?',['The typed name','The greeting displayed afterward','The color of a displayed greeting','A sound played afterward'],'The typed name is data supplied by the person.'],
      ['Hard','Which observation best shows that a club-information app fulfills its purpose?',['Students can find the meeting time and location','The app has more lines of code than last week','All buttons are the same color','The developer used every toolbox command'],'Evaluate purpose through the user’s ability to accomplish the intended task.']
    ]],
    ['design', 'Interface & user-centered design', 'Design Mode, screen elements, and useful feedback.', [
      ['Easy','What is a user interface?',['The parts of an app a user sees and interacts with','Only the comments in source code','Only the programmer’s keyboard','The language used by a computer’s processor'],'An interface includes screens, controls, text, and other elements users interact with.'],
      ['Easy','What is App Lab’s Design Mode mainly used for?',['Arranging screen elements and their properties','Testing every possible button sequence automatically','Writing console messages only','Converting JavaScript to natural language'],'Design Mode lets you build screens and configure elements such as buttons and labels.'],
      ['Medium','Which button label best helps users reach a schedule screen?',['View schedule','Do thing','Button 2','Click maybe'],'A clear, task-specific label tells users what to expect.'],
      ['Medium','Students keep missing a small navigation button on a phone. Which change best addresses that feedback?',['Make the button larger and easier to find','Add more source-code comments','Rename an unrelated label’s ID','Hide the navigation button'],'Changes should address the observed usability problem.'],
      ['Easy','Why give each App Lab element a distinct ID?',['Code needs a way to refer to the intended element','IDs automatically translate all text','IDs determine how quickly users type','IDs replace event handlers'],'IDs identify elements so commands and event handlers can target them.'],
      ['Medium','A prototype is most useful for which early activity?',['Trying a design and gathering feedback before polishing it','Guaranteeing that the final app has no errors','Replacing all user testing','Making every design decision permanent'],'A prototype makes ideas concrete so users can try them and guide improvements.'],
      ['Hard','Which test provides the best evidence that new users can navigate an app?',['Ask intended users to find a page without giving directions','Tell each user exactly which buttons to press','Only ask the programmer whether it looks nice','Count the number of screen elements'],'Watching users attempt a real task reveals navigation problems that instructions can hide.'],
      ['Medium','An app uses tiny gray text on a gray background. What is the most useful design revision?',['Increase text readability with size and contrast','Add more sound effects','Use less descriptive button labels','Move all text into the Debug Console'],'Readable text supports access to information and successful use.'],
      ['Hard','Two testers give conflicting feedback about button size. What is the best next step?',['Test the task with more intended users and compare what they struggle with','Ignore all feedback','Always accept the last comment','Choose whichever option requires more code'],'User-centered decisions rely on evidence about the intended users and their tasks.'],
      ['Medium','A team sketches screens and draws arrows between them. What are the arrows most likely representing?',['Navigation paths between screens','Automatic changes in programming language','The order of every comment','The number of random values generated'],'A screen plan can show which user actions lead to which screens.']
    ]],
    ['sequence', 'Language & sequential execution', 'Statements, precise instructions, and tracing order.', [
      ['Easy','Why do programming languages need precise syntax?',['A computer must interpret instructions according to defined rules','Computers always guess what the author intended','Punctuation changes only the appearance of code','Natural language has no meaning'],'Programming syntax gives instructions an unambiguous structure the environment can interpret.'],
      ['Easy','What is a program statement?',['An instruction expressing an action to carry out','A screen’s decorative border','A user’s opinion about an app','A sound file'],'Statements tell a computer what actions to perform.'],
      ['Easy','In simple sequential code, how are statements normally executed?',['In their written order','In alphabetical order','From the shortest line to the longest','In a new random order each time'],'Sequential execution follows the order of statements.'],
      ['Medium','What appears in the Debug Console, in order?',['First, then Second','Second, then First','Only First','Nothing until a button is clicked'],'Both statements are outside event handlers and run in order.','console.log("First");\nconsole.log("Second");'],
      ['Medium','Assume status is an existing label. What text does it have after both statements finish?',['Done','Loading','LoadingDone','It has no text'],'The second statement replaces the text set by the first.','setProperty("status", "text", "Loading");\nsetProperty("status", "text", "Done");'],
      ['Hard','Assume badge is an existing label. What are its final text and text color?',['Go and blue','Wait and blue','Go and red','Wait and red'],'Text and color are separate properties. The final text assignment replaces Wait; the color remains blue.','setProperty("badge", "text", "Wait");\nsetProperty("badge", "text-color", "blue");\nsetProperty("badge", "text", "Go");'],
      ['Medium','Which phrase is a natural-language instruction rather than App Lab code?',['Make the label say Welcome','console.log("Welcome");','setScreen("home");','setProperty("title", "text", "Welcome");'],'Natural language can describe a goal; executable code must follow the programming language’s rules.'],
      ['Hard','Assume both screens exist. Which screen is visible after startup code finishes?',['homeScreen','helpScreen','Both at once','Neither because two calls cancel'],'Each setScreen call changes the displayed screen; the last call selects homeScreen.','setScreen("helpScreen");\nconsole.log("Switching");\nsetScreen("homeScreen");'],
      ['Medium','What does running a program mean?',['Having the computer execute its instructions','Only reading the comments aloud','Renaming every screen','Automatically finding all mistakes'],'Execution means carrying out program instructions.'],
      ['Hard','Which revision makes the console display B before A?',['Swap the two console.log statements','Change the comment to say B first','Rename the app','Make a button wider'],'Changing statement order changes the order of sequential output. Comments do not control execution.','// Display letters\nconsole.log("A");\nconsole.log("B");']
    ]],
    ['events', 'Events & onEvent()', 'User actions, handlers, and startup versus interaction.', [
      ['Easy','Which is an event in an interactive app?',['A user clicking a button','A note in a comment','A screen ID written in quotes','The name JavaScript'],'An event is an occurrence the program can respond to, such as a click.'],
      ['Easy','What is an event handler?',['Code that runs in response to a specified event','A list of all screen colors','A comment at the top of a program','A tool that removes every bug'],'A handler defines what the app should do when the specified event occurs.'],
      ['Medium','When does this code log “Saved”? Assume saveButton exists.',['When saveButton is clicked','As soon as the handler is registered','Whenever any button is clicked','Only when the app closes'],'onEvent registers a handler; its body runs when the specified button receives a click.','onEvent("saveButton", "click", function() {\n  console.log("Saved");\n});'],
      ['Medium','What is the second argument, "click", specifying?',['The event type to listen for','The destination screen','The label text','The code comment'],'The arguments identify the element, the event type, and the handler.','onEvent("nextButton", "click", function() {\n  setScreen("detailsScreen");\n});'],
      ['Hard','No one clicks the button. What appears in the console at startup?',['Start, then Ready','Start, Tap, Ready','Tap only','Ready, then Start'],'The handler is registered without executing its body. The surrounding console statements run sequentially.','console.log("Start");\nonEvent("tapButton", "click", function() {\n  console.log("Tap");\n});\nconsole.log("Ready");'],
      ['Hard','After startup, the user clicks tapButton twice. What is the full console sequence?',['Ready, Tap, Tap','Tap, Ready, Tap','Ready, Tap','Tap, Tap, Ready'],'Ready runs once at startup; each click invokes the handler again.','onEvent("tapButton", "click", function() {\n  console.log("Tap");\n});\nconsole.log("Ready");'],
      ['Medium','Which code correctly waits for a click on infoButton before opening infoScreen?',['onEvent("infoButton", "click", function() { setScreen("infoScreen"); });','setScreen("infoButton");','onEvent("infoScreen", "click", function() { setScreen("infoButton"); });','console.log("infoScreen");'],'The handler listens to the button and switches to the screen when clicked.'],
      ['Medium','Assume label starts as “Before”. With no clicks, what text does it show after startup?',['After','Clicked','Before','AfterClicked'],'The last statement runs at startup; the handler’s text change waits for a click.','onEvent("button", "click", function() {\n  setProperty("label", "text", "Clicked");\n});\nsetProperty("label", "text", "After");'],
      ['Hard','A button should change a label only when clicked, but it changes at startup. What is the best fix?',['Move the setProperty statement inside the button’s click handler','Move the statement above all comments','Change the label’s color','Add a console message after the statement'],'Placing the action inside the handler ties it to the event rather than startup.'],
      ['Easy','What distinguishes event-driven programming from a purely sequential script?',['Some actions happen in response to events rather than all happening at startup','All statements run backward','It cannot contain sequential statements','It never accepts user input'],'Event-driven apps respond to events; statements within a handler still execute in sequence.']
    ]],
    ['properties', 'App Lab & setProperty()', 'Element IDs, values, and changing interface properties.', [
      ['Easy','What does setProperty() do?',['Changes a specified property of a screen element','Creates a new programming language','Always switches to another screen','Registers a click handler'],'setProperty targets an element and updates one of its properties.'],
      ['Easy','What do the three arguments identify, in order?',['Element ID, property name, new value','New value, screen ID, event type','Event type, element ID, comment','Property name, new value, element ID'],'setProperty uses the element ID first, then the property, then its new value.','setProperty("title", "text", "Hello");'],
      ['Medium','Which command correctly changes the existing label message to display “Nice work”?',['setProperty("message", "text", "Nice work");','setProperty("text", "message", "Nice work");','setScreen("Nice work");','console.log("message");'],'The label’s ID is message; text is the property; Nice work is the new string value.'],
      ['Medium','Which property changes a button’s background color?',['"background-color"','"click"','"screen"','"comment"'],'background-color is the property for an element’s background color.'],
      ['Medium','Assume banner exists. Which property is changed here?',['The color of its text','The displayed text itself','The active screen','Its element ID'],'text-color controls the text’s color; it does not replace the text.','setProperty("banner", "text-color", "green");'],
      ['Hard','Assume both labels exist. What text is finally displayed on leftLabel?',['Three','One','Two','OneThree'],'Each ID targets a separate element. Only the first and third statements change leftLabel, and the third wins.','setProperty("leftLabel", "text", "One");\nsetProperty("rightLabel", "text", "Two");\nsetProperty("leftLabel", "text", "Three");'],
      ['Medium','Which command sets an existing button’s width to 120 pixels?',['setProperty("goButton", "width", 120);','setProperty(120, "width", "goButton");','setScreen(120);','onEvent("goButton", "width", function() {});'],'width is a numeric property; the ID and property name are strings.'],
      ['Hard','A label’s ID is resultLabel, but its visible text is “Result”. Which command updates it correctly?',['setProperty("resultLabel", "text", "Finished");','setProperty("Result", "text", "Finished");','setProperty("Finished", "text", "resultLabel");','console.log("Result");'],'Commands use the element’s ID, which can differ from the text displayed to users.'],
      ['Medium','Assume photo is an existing image element and lake.png is an uploaded asset. Which command changes its image?',['setProperty("photo", "image", "lake.png");','setProperty("photo", "click", "lake.png");','setScreen("lake.png");','console.log("lake.png");'],'For an image element, image is the property that specifies the displayed image asset.'],
      ['Hard','Assume box is an existing element. Which description is correct after this code?',['Its x position is 50 and width is 90','Its x position is 90 and width is 50','Both properties are 90','The second command deletes the first property'],'Different properties keep their own values; changing width does not overwrite x.','setProperty("box", "x", 50);\nsetProperty("box", "width", 90);']
    ]],
    ['commands', 'Screens, sound & random numbers', 'setScreen(), console.log(), playSound(), and randomNumber().', [
      ['Easy','What does setScreen("menuScreen") do if that screen exists?',['Makes menuScreen the displayed screen','Renames every button','Prints menuScreen in the console','Plays a sound named menuScreen'],'setScreen switches the app’s displayed screen by ID.'],
      ['Easy','Where does console.log("Checking") display its message in App Lab?',['The Debug Console','Automatically in every label','In the screen’s title bar','As an audio announcement'],'console.log produces a message in the Debug Console, useful for observing execution.'],
      ['Medium','Assume bell.mp3 is an uploaded sound. What is the intended effect?',['Play the sound once without looping','Play it forever','Switch to a sound screen','Print the file name on the app screen'],'playSound plays the specified asset; false requests no looping.','playSound("bell.mp3", false);'],
      ['Easy','Which values can randomNumber(2, 5) return?',['2, 3, 4, or 5','Only 2 or 5','Any decimal from 2 to 5','Only 3 or 4'],'randomNumber returns an integer and includes both endpoints.'],
      ['Medium','Which command models rolling a standard six-sided die?',['randomNumber(1, 6)','randomNumber(0, 6)','randomNumber(1, 5)','randomNumber(6, 6)'],'A standard die has integer outcomes 1 through 6, inclusive.'],
      ['Hard','What can be concluded about these two console messages?',['Each is an integer from 1 to 3; they might be equal or different','The second is always larger','They must be different','They are always both 2'],'Each call generates a number in the specified inclusive range; a repeated value is possible.','console.log(randomNumber(1, 3));\nconsole.log(randomNumber(1, 3));'],
      ['Medium','Which command changes an app label rather than writing only to the console?',['setProperty("status", "text", "Ready");','console.log("Ready");','console.log("status");','randomNumber(1, 4);'],'setProperty updates the interface. Console messages do not automatically update labels.'],
      ['Hard','A 320-pixel-wide screen contains a 40-pixel-wide image. Its x position must keep the whole image inside. Which range fits?',['randomNumber(0, 280)','randomNumber(0, 320)','randomNumber(280, 320)','randomNumber(-40, 320)'],'The right edge is x + 40, so x can be at most 280 and at least 0.'],
      ['Medium','A click handler contains setScreen("helpScreen"). What does the quoted argument need to match?',['The destination screen’s ID','The visible text of the clicked button','The name of the sound file','The click event type'],'setScreen expects the ID of a screen, not a button label or event name.'],
      ['Hard','Assume both screens exist. After clicking goButton, which screen is visible when its handler finishes?',['summaryScreen','detailScreen','Both screens simultaneously','The original screen'],'Statements within the handler execute sequentially; the last setScreen determines the visible screen.','onEvent("goButton", "click", function() {\n  setScreen("detailScreen");\n  console.log("Moving on");\n  setScreen("summaryScreen");\n});']
    ]],
    ['documentation', 'Strings, comments & documentation', 'Text values and explaining code to people.', [
      ['Easy','Which is a string in JavaScript?',['"Welcome"','42','// Welcome','console.log'],'A string is text represented inside matching quotation marks.'],
      ['Easy','What does // begin outside a string?',['A single-line comment','A screen transition','A random number','A click event'],'Outside a string, // makes the rest of that line a comment.'],
      ['Medium','What does this code print?',['Hello','Ignored, then Hello','Only Ignored','Nothing'],'The commented-out call is not executed; the second call is.','// console.log("Ignored");\nconsole.log("Hello");'],
      ['Medium','What happens when a developer changes only an explanatory comment?',['The program’s behavior stays the same','The program automatically runs faster','All event handlers stop working','The active screen changes'],'Comments are for people and do not execute.'],
      ['Medium','Which comment most usefully documents this handler?',['// Open the menu when the user presses Back','// This is code','// Three lines follow','// Blue is my favorite color'],'A useful comment explains the action or intent rather than an unrelated fact.','onEvent("backButton", "click", function() {\n  setScreen("menuScreen");\n});'],
      ['Hard','What is printed in the Debug Console?',['// This is text','Nothing because the whole line is a comment','This is text without the slashes','A syntax error because strings cannot contain slashes'],'The slashes are inside a quoted string, so they are part of the text.','console.log("// This is text");'],
      ['Medium','Which is valid code for displaying the string Go in the console?',['console.log("Go");','console.log("Go);','console.log(Go");','console.log("Go";'],'The string has matching quotes and the call has matching parentheses.'],
      ['Easy','Why write documentation during app development?',['Help people understand the program and how to work on it','Force the computer to ignore all errors','Make user testing unnecessary','Automatically add missing screens'],'Documentation records purpose, behavior, and useful details for people maintaining or using the app.'],
      ['Hard','Which line logs the text 7 rather than the numeric value 7?',['console.log("7");','console.log(7);','// console.log("7");','setScreen("7");'],'Quotes make 7 a string. The console may look similar, but the value supplied is text.'],
      ['Medium','An element ID is helpButton. Why is it written as "helpButton" in onEvent()?',['The argument identifies the element using a string','Quotes tell the app to play a sound','Quotes make the handler run at startup','Quotes turn the whole handler into a comment'],'The element ID is passed as a string value.']
    ]],
    ['debugging', 'Debugging, testing & iteration', 'Find problems, test fixes, and improve with feedback.', [
      ['Easy','What is debugging?',['Finding and fixing problems in a program','Adding a new screen every day','Replacing all comments with code','Choosing a font for the app title'],'Debugging identifies causes of unexpected behavior and corrects them.'],
      ['Medium','The only destination screen has ID infoScreen. Why does this command fail to select it?',['The ID’s capitalization does not match','setScreen requires three arguments','The command should be a comment','The screen must contain a sound'],'IDs must match exactly, including capitalization.','setScreen("InfoScreen");'],
      ['Medium','No variable named blue is defined. Which correction supplies the intended color string?',['setProperty("button", "background-color", "blue");','setProperty("button", "background-color", Blue);','setProperty("blue", "background-color", "button");','console.log("blue");'],'A color name supplied as text needs quotes. The original treats blue as an identifier.','setProperty("button", "background-color", blue);'],
      ['Medium','An app runs without warnings but its Back button opens the wrong screen. What does this show?',['A program can run yet still behave incorrectly','No warnings proves the program is correct','All screen navigation errors are syntax errors','User testing cannot find errors'],'Testing is needed to detect behavior that differs from the intended result, even when syntax is valid.'],
      ['Hard','What is the most informative first step when a button seems to do nothing?',['Check its ID and event type, then add a console message inside its handler','Rewrite the entire app immediately','Add random comments everywhere','Change the app’s background color'],'Check whether the intended event reaches the handler before changing unrelated code.'],
      ['Medium','After fixing a navigation bug, what should a team do next?',['Repeat the failing steps and check related navigation paths','Assume changing code guarantees the bug is gone','Remove every event handler','Stop testing for the rest of the project'],'Re-testing verifies the fix and checks for effects on related behavior.'],
      ['Easy','Which sequence illustrates iterative development?',['Build a prototype → test → revise → test again','Build once → ignore feedback','Document once → never run','Test only before writing any code'],'Iteration repeats development and evaluation to improve the app.'],
      ['Hard','A tester reports “It broke.” Which follow-up gives the most useful debugging information?',['Ask what actions they took, what they expected, and what actually happened','Ask their favorite color only','Ask them to count all source-code comments','Ask whether the app has a short name'],'Steps, expected behavior, and observed behavior help reproduce and locate a problem.'],
      ['Medium','Which test plan best checks a two-screen app with Home and Help navigation?',['Try both directions and repeat the actions from their intended starting screens','Click Help once and never return','Inspect only the source-code formatting','Check only the first screen’s color'],'Testing each navigation path checks whether both handlers and destination IDs work.'],
      ['Hard','Three users cannot tell how to return from the details screen. What is the best evidence-based iteration?',['Add a clearly labeled Back control and test whether users can return','Add an unrelated sound at startup','Rename a private source file','Leave the app unchanged because it has no syntax errors'],'Observed user difficulty should guide a relevant interface change, followed by another test.']
    ]]
  ];
  root.TOPICS = groups.map(([id,name,description])=>({id,name,description}));
  root.QUESTIONS = groups.flatMap(([topic,,,rows])=>rows.map((r,i)=>({id:topic+'-'+String(i+1).padStart(2,'0'),topic,difficulty:r[0],question:r[1],choices:r[2],correctAnswer:0,explanation:r[3],code:r[4]||null})));
})(typeof window === 'undefined' ? globalThis : window);
